-- 000035_seed_move_commands.down.sql
-- M17-02: command 索引 move_commands の seed(非派生のみ・CHANGE-069 §2.1-b)
-- 本ファイルは cmd/seedgen が character_data/*.csv から生成した成果物(手編集しない)。
-- 非派生技(is_derived=false)のみ搭載。token_key は numpad 正規化済み(internal/moveindex が一元管理)。
-- 索引は広く持つ(必殺技・空中技も搭載)＝段階2 スコープへの絞り込みは消費者側(CHANGE-069 §1.5-6)。
-- 既存マイグレは非改変(新規連番で追加)。FK 依存順 characters→moves→move_commands。

-- ===== ryu =====
DELETE FROM move_commands WHERE move_id IN (
    SELECT m.id FROM moves m JOIN characters c ON c.id = m.character_id WHERE c.code = 'ryu' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6') AND m.code IN ('sa2_shin_hashogeki_lv1', 'sa2_shin_hashogeki_lv2', 'sa2_shin_hashogeki_lv3', 'tatsumaki_senpu_kyaku_heavy', 'hashogeki_heavy', 'aerial_tatsumaki_senpu_kyaku', 'tatsumaki_senpu_kyaku_od', 'aerial_tatsumaki_senpu_kyaku_od', 'tatsumaki_senpu_kyaku_light', 'hashogeki_light', 'tatsumaki_senpu_kyaku_medium', 'hashogeki_medium', 'hashogeki_od', 'denjin_charge', 'sa3_shin_shoryuken', 'ca_shin_shoryuken', 'sa1_shinku_hadoken', 'high_blade_kick_heavy', 'hadoken_heavy', 'high_blade_kick_od', 'high_blade_kick_light', 'hadoken_light', 'high_blade_kick_medium', 'hadoken_medium', 'hadoken_od', 'crouching_heavy_kick', 'crouching_heavy_punch', 'crouching_light_kick', 'crouching_light_punch', 'crouching_medium_kick', 'crouching_medium_punch', 'axe_kick', 'short_uppercut', 'throw_back', 'throw_forward', 'shoryuken_heavy', 'shoryuken_light', 'shoryuken_medium', 'shoryuken_od', 'whirlwind_kick', 'solar_plexus_strike', 'collarbone_breaker', 'standing_heavy_kick', 'jumping_heavy_kick', 'standing_heavy_punch', 'jumping_heavy_punch', 'drive_impact', 'standing_light_kick', 'jumping_light_kick', 'standing_light_punch', 'jumping_light_punch', 'standing_medium_kick', 'jumping_medium_kick', 'standing_medium_punch', 'jumping_medium_punch', 'drive_parry'));

